// telegram_web_login() -> one reply (D-103); nothing for someone who is not an approver. Telegram
// text is Vietnamese (D-061). The deploy script fills the URL in; empty until the console is set up.
const WEB_CONSOLE_URL = 'REPLACE_WITH_WEB_CONSOLE_URL';
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = (text) => [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];
if (row.result === 'NOT_PRIVATE') return reply('Link đăng nhập chỉ gửi trong chat riêng. Hãy nhắn /web riêng cho bot.');
if (row.result !== 'OK') return [];
if (!WEB_CONSOLE_URL) return reply('Trang quản lý chưa được cài đặt.');
return reply(`Đăng nhập trang quản lý, link dùng một lần, hết hạn sau 5 phút:\n${WEB_CONSOLE_URL}/login?t=${row.token}`);

// telegram_deploy() -> one reply (D-100). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = (text) => [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];
if (row.result === 'NOT_OWNER') return reply('Chỉ owner mới deploy được.');
if (row.result === 'OK') {
  return reply('🚀 Đang kiểm tra origin/main; bot sẽ gửi nút xác nhận trong khoảng 1 phút.');
}
const targets = (row.targets ?? []).map((t) => `${t.target}: ${t.status}`);
return reply([
  `Đang có một lần deploy (${row.status})${row.sha ? ` · ${String(row.sha).slice(0, 7)}` : ''}.`,
  ...targets,
].join('\n'));

// telegram_report() -> one message (D-099). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = (text) => [{ json: { text: text.slice(0, 4096), chatId: input.chatId, messageId: input.messageId } }];
if (row.allowed !== true) return reply('Bạn không phải approver.');
const PERIODS = { today: 'hôm nay', '7d': '7 ngày', '30d': '30 ngày' };
const round = (value) => Math.round(value * 100) / 100;
const money = (costs) => Object.entries(costs ?? {}).map(([currency, amount]) => `${round(amount)} ${currency}`).join(', ');
const duration = (seconds) => {
  const m = Math.round(seconds / 60);
  return m < 60 ? `${m} phút` : `${Math.floor(m / 60)} giờ ${String(m % 60).padStart(2, '0')} phút`;
};
const since = new Date(new Date(row.since).getTime() + 7 * 3_600_000);
const p = (n) => String(n).padStart(2, '0');
const sinceText = `${p(since.getUTCHours())}:${p(since.getUTCMinutes())} ${p(since.getUTCDate())}/${p(since.getUTCMonth() + 1)}`;
const perMinute = Object.entries(row.completed_cost ?? {}).map(([currency, amount]) => `${round(amount / row.minutes)} ${currency}/phút`).join(', ');
const steps = row.steps ?? [];
const decided = row.approvals?.decided ?? 0;
return reply([
  `📈 Báo cáo ${PERIODS[row.period] ?? row.period} (từ ${sinceText})`,
  '',
  `Video: ${row.completed} xong · ${row.failed} lỗi · ${row.cancelled} hủy · ${row.created} mới tạo`,
  `Hiện tại: ${row.active} đang chạy, ${row.stopped} đang dừng`,
  `Chi phí đã ghi nhận: ${money(row.cost) || 'chưa có'}`,
  row.minutes_videos > 0 && perMinute
    ? `Chi phí mỗi phút: ${perMinute} (${row.minutes_videos} video, ${round(row.minutes)} phút)`
    : 'Chi phí mỗi phút: chưa có video nào đo được độ dài',
  ...(steps.length ? ['', 'Bước lâu nhất (trung vị):', ...steps.map((s) => `${s.step} · ${duration(s.median_seconds)} · ${s.runs} lần`)] : []),
  '',
  decided ? `Duyệt: ${decided} lần, chờ trung vị ${duration(row.approvals.median_seconds)}` : 'Duyệt: chưa có',
].join('\n'));

// telegram_cancel() / telegram_auto_all() -> a preview with Confirm buttons, or one reply without
// them (D-098). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const answer = (text) => [{ json: { ok: false, text: text.slice(0, 4096), chatId: input.chatId, messageId: input.messageId } }];
const items = row.items ?? [];
const short = (id) => String(id).slice(0, 8);
const video = (item) => [`${short(item.video_id)} v${item.version}`, item.title ?? '?', item.status].join(' · ');
const refused = {
  NOT_OWNER: 'Chỉ owner mới hủy được video.',
  TOO_MANY: 'Mỗi lần hủy tối đa 20 video.',
  NOT_APPROVER: 'Bạn không phải approver.',
};
if (refused[row.result]) return answer(refused[row.result]);
if (input.kind === 'auto-all' && row.result === 'OFF') {
  return answer(`Đã tắt tự duyệt cho ${items.length} video; các bước sau gửi nút duyệt như thường.`);
}
const ask = (text) => [{
  json: {
    ok: true,
    text: text.slice(0, 4096),
    approve: `cf:A:${row.token}`,
    reject: `cf:R:${row.token}`,
    chatId: input.chatId,
    messageId: input.messageId,
  },
}];
const HOW_LONG = 'Nút hết hạn sau 10 phút; chỉ người gửi lệnh mới bấm được.';
if (input.kind === 'cancel') {
  const reason = (item) => {
    if (input.fromCard && !item.video_id) return 'Video đã có bản mới; gửi lại /v <id>.';
    const label = input.fromCard ? short(item.video_id) : item.ref;
    if (item.result === 'NOT_FOUND') return `${label}: không tìm thấy`;
    if (item.result === 'AMBIGUOUS') return `${label}: nhiều video trùng, gõ thêm ký tự`;
    return `${label}: đã ${String(item.result).replace('ALREADY_', '')}`;
  };
  const will = items.filter((item) => item.result === 'WOULD_CANCEL');
  const skipped = items.filter((item) => item.result !== 'WOULD_CANCEL').map(reason);
  if (row.result !== 'OK') return answer(['Không có video nào để hủy.', '', ...skipped].join('\n'));
  return ask([
    `🛑 Hủy ${will.length} video?`,
    '',
    ...will.map(video),
    ...(skipped.length ? ['', ...skipped] : []),
    '',
    'Không xóa file nào. Job đang chạy sẽ chạy nốt nhưng kết quả bị bỏ; credit đã dùng không được hoàn lại.',
    HOW_LONG,
  ].join('\n'));
}
if (row.result !== 'OK') return answer('Không có video nào để bật tự duyệt.');
const money = Object.entries(row.estimates ?? {}).map(([currency, amount]) => `${Math.round(amount * 100) / 100} ${currency}`).join(', ');
return ask([
  `🤖 Bật tự duyệt cho ${items.length} video?`,
  '',
  ...items.map((item) => [video(item), ...(item.gate ? [`chờ ${item.gate}`] : [])].join(' · ')),
  '',
  ...(row.gates ? [`${row.gates} bước đang chờ sẽ được duyệt ngay.`] : []),
  `Chi phí TTS ước tính đã ghi: ${money || 'chưa có'}${row.no_estimate ? ` (${row.no_estimate} video chưa có ước tính)` : ''}.`,
  'QA FAIL vẫn dừng lại hỏi, bước xóa bản trên Mac vẫn hỏi owner, video tạo sau vẫn duyệt tay.',
  HOW_LONG,
].join('\n'));

// telegram_confirm() -> the answer to the button and, once settled, the message without its
// buttons (D-098). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const items = row.items ?? [];
const short = (id) => String(id).slice(0, 8);
const fixed = {
  NOT_REQUESTER: 'Chỉ người gửi lệnh mới xác nhận được.',
  NOT_ALLOWED: 'Bạn không còn quyền làm việc này.',
  REJECTED: 'Đã bỏ qua.',
  EXPIRED: 'Đã hết hạn; gửi lại lệnh nếu vẫn cần.',
  ALREADY: 'Yêu cầu này đã xử lý rồi.',
  NOT_FOUND: 'Yêu cầu này đã xử lý rồi.',
};
const cancelled = row.action === 'CANCEL';
const done = items.filter((item) => item.result === (cancelled ? 'CANCELLED' : 'OK'));
const problem = (item) => {
  if (item.result === 'STALE') return `${short(item.video_id)}: đã có bản mới, không ${cancelled ? 'hủy' : 'bật'}`;
  if (item.result === 'ERROR') return `${short(item.video_id)}: lỗi, xem log`;
  return `${short(item.video_id)}: bỏ qua (${item.result})`;
};
const decided = items.filter((item) => item.decided_type).length;
const success = {
  CANCEL: `Đã hủy ${done.length} video.`,
  AUTO_ALL: `Đã bật tự duyệt cho ${done.length} video.`,
  DEPLOY: 'Đã bắt đầu deploy; có thông báo khi xong.',
};
const answer = fixed[row.result] ?? success[row.action];
return [{
  json: {
    answer,
    settled: !['NOT_REQUESTER', 'NOT_ALLOWED'].includes(row.result),
    queryId: input.queryId,
    chatId: input.chatId,
    messageId: input.messageId,
    editedHtml: [
      `<b>${row.result === 'OK' ? '✔️' : '⏹'} ${esc(answer)}</b>`,
      ...(decided ? [`Đã duyệt luôn ${decided} bước đang chờ.`] : []),
      ...items.filter((item) => !done.includes(item)).map((item) => esc(problem(item))),
    ].join('\n').slice(0, 4096),
  },
}];

// /help and usage replies (D-097). Telegram text is Vietnamese (D-061). Approvers get an answer
// anywhere, anyone in the approval chat; nobody else. A command nobody knows that names a bot is
// meant for that bot and gets no answer.
const input = $('Parse callback').first().json;
const allowed = $input.first()?.json?.allowed === true || input.inApprovalChat === true;
if (!allowed) return [];
const reply = (text) => [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];
const ALIASES = { video: 'v', huy: 'cancel', cho: 'pending', worker: 'workers', ytuong: 'ideas', tudong: 'auto', chuyen: 'move' };
const USAGE = {
  new: '/new [số phút] <chủ đề> [kit=<kit>] [nhanvat=<nhân vật>] [worker=<worker>] [auto=on], ghi chú ở các dòng sau; full brief: gửi file .md hoặc .txt với lệnh này làm caption',
  brief: '/brief: mẫu prompt để LLM khác viết full brief',
  ideas: '/ideas [kit=<kit>] [nhanvat=<nhân vật>]',
  status: '/status [<id>]: các video đang chạy, hoặc chi tiết một video',
  v: '/v <id>: chi tiết một video kèm nút chạy lại, tự duyệt, gửi lại duyệt, hủy',
  report: '/report [today|7d|30d]: số video, chi phí, bước lâu nhất, thời gian chờ duyệt',
  workers: '/workers: worker nào đang chạy clip nào · /worker <worker>: chi tiết một worker',
  pending: '/pending [<id>]: gửi lại yêu cầu duyệt đang chờ, liệt kê video đang dừng',
  retry: '/retry <id>: chạy lại bước lỗi của video đang dừng',
  auto: '/auto <id> [off]: tự duyệt mọi bước tới khi lưu Drive; off để tắt · /auto all [off]: mọi video đang chạy, có nút xác nhận',
  cancel: '/cancel <id> [id...]: hủy video (owner), có nút xác nhận; tối đa 20 video',
  move: '/move <id> <worker>: chuyển video sang worker khác (owner); /move <id> huy để hủy',
  rules: '/rules [video|tts|say] · /rules file <video|tts|say> · gửi file .md/.txt với caption /rules set <video|tts|say>',
  rule: '/rule add <video|tts> <nội dung> · /rule del <số>',
  say: '/say <từ> = <cách đọc>',
  unsay: '/unsay <từ>',
  deploy: '/deploy: cập nhật worker và n8n lên origin/main (owner), có kiểm tra trước và nút xác nhận',
  web: '/web: link đăng nhập trang quản lý, dùng một lần; chỉ gửi trong chat riêng với bot',
  join: '/join: xin làm approver (owner duyệt)',
  members: '/members: danh sách approver',
  revoke: '/revoke <user id>: bỏ quyền approver (owner)',
  help: '/help [lệnh]: danh sách lệnh, hoặc cách dùng một lệnh',
};
const GROUPS = [
  ['🎬 Tạo video', ['new', 'brief', 'ideas']],
  ['📊 Theo dõi', ['status', 'v', 'workers', 'pending', 'report']],
  ['🎛 Điều khiển video', ['retry', 'auto', 'cancel', 'move']],
  ['📝 Quy tắc kênh', ['rules', 'rule', 'say', 'unsay']],
  ['👥 Thành viên', ['join', 'members', 'revoke']],
  ['🚀 Vận hành', ['web', 'deploy']],
];
if (input.mode === 'help' && input.topic === '') {
  return reply([
    ...GROUPS.flatMap(([title, names]) => [title, ...names.map((name) => USAGE[name]), '']),
    USAGE.help,
    '<id> là 8 ký tự đầu của id video, hoặc last cho video mới nhất chưa kết thúc.',
    'Lệnh bot gợi ý có thể bấm luôn: /retry_679cd22f chạy như /retry 679cd22f.',
  ].join('\n'));
}
const name = ALIASES[input.topic] ?? input.topic;
const usage = Object.hasOwn(USAGE, name) ? USAGE[name] : null;
if (usage === null) {
  return input.addressed ? [] : reply(`Không có lệnh /${input.topic}. Xem /help.`);
}
return reply(`Cách dùng: ${usage}`);

// /web, /status, /v, /report, /deploy, /workers, /pending, /retry, /auto, /new, /ideas, /help, rules and member commands, idea buttons, well-formed A1 / A1b voice / storyboard / A2 /
// intake / member / A3 / cleanup buttons, and replies with notes to an A1, storyboard, A2 or A3 request reach
// the database; anything else is ignored. Storyboard requests (WF-12) end with "ref:<token>".
const rawUpdate = $input.first().json;
// One-tap commands (D-102): Telegram makes only letters, digits and _ tappable, so the bot suggests
// /retry_679cd22f. It becomes the typed form here and every check below applies as if typed.
// /auto <id> (on) and /cancel have no tap form on purpose: the first approves a waiting gate at once
// and the second is never suggested. Worker ids have no _ (WORKER_ID), so the mapping is lossless.
const TAP_FORMS = [
  [/^(status|v|retry|pending)_([0-9a-fA-F]{4,36})$/, '$1 $2'],
  [/^auto_([0-9a-fA-F]{4,36})_off$/, 'auto $1 off'],
  [/^move_([0-9a-fA-F]{4,36})_huy$/, 'move $1 huy'],
  [/^worker_([a-z0-9_]{3,64})$/, (_, id) => `worker ${id.replace(/_/g, '-')}`],
];
const tap = /^\/(\w+)(@\w+)?\s*$/.exec(rawUpdate.message?.text ?? '');
const tapForm = tap && TAP_FORMS.find(([pattern]) => pattern.test(tap[1]));
const update = tapForm
  ? {
      ...rawUpdate,
      message: {
        ...rawUpdate.message,
        text: `/${tap[1].replace(tapForm[0], tapForm[1]).replace(' ', `${tap[2] ?? ''} `)}`,
      },
    }
  : rawUpdate;
// /status [video id prefix] (P-017) is answered from telegram_status(); approvers only.
const statusCommand = /^\/status(?:@\w+)?(?:\s+([0-9a-fA-F-]{1,36}|last))?\s*$/.exec(update.message?.text ?? '');
if (update.message && statusCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'status',
      prefix: (statusCommand[1] ?? '').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /v <video id prefix> (D-099; alias /video) is /status <id> with a button per action.
const cardCommand = /^\/(?:v|video)(?:@\w+)?\s+([0-9a-fA-F-]{4,36}|last)\s*$/.exec(update.message?.text ?? '');
if (update.message && cardCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'status',
      card: true,
      prefix: cardCommand[1].toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /report [today|7d|30d] (D-099) comes from telegram_report(); approvers only.
const reportCommand = /^\/report(?:@\w+)?(?:\s+(today|7d|30d))?\s*$/.exec(update.message?.text ?? '');
if (update.message && reportCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'report',
      period: reportCommand[1] ?? 'today',
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /deploy (D-100) takes no arguments: it can only offer origin/main, and only the owner, after a
// preflight and a Confirm button. telegram_deploy() checks the owner.
if (update.message && /^\/deploy(?:@\w+)?\s*$/.test(update.message.text ?? '') && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'deploy',
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /workers (D-082) shows what each worker is running, from telegram_workers(); with an exact worker
// id (D-102) that worker's detail, from telegram_worker_detail(); approvers only.
const workersCommand = /^\/workers?(?:@\w+)?(?:\s+([0-9a-zA-Z-]{3,64}))?\s*$/.exec(update.message?.text ?? '');
if (update.message && workersCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      ...(workersCommand[1] ? { kind: 'worker', worker: workersCommand[1].toLowerCase() } : { kind: 'workers' }),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /pending [video id prefix] (D-090; alias /cho) lists the open approval requests and has
// WF-05/12/13/14/15 send them again with their buttons; telegram_pending() checks the user.
const pendingCommand = /^\/(?:pending|cho)(?:@\w+)?(?:\s+([0-9a-fA-F-]{1,36}|last))?\s*$/.exec(update.message?.text ?? '');
if (update.message && pendingCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'pending',
      prefix: (pendingCommand[1] ?? '').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /cancel <video id prefix> ... (D-098; alias /huy) shows what it would cancel, with a Confirm
// button; telegram_cancel() checks the owner. Anything else falls through to the usage reply.
const cancelCommand = /^\/(?:cancel|huy)(?:@\w+)?((?:\s+(?:[0-9a-fA-F-]{4,36}|last))+)\s*$/.exec(update.message?.text ?? '');
if (update.message && cancelCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'cancel',
      refs: cancelCommand[1].trim().split(/\s+/).join(' ').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /retry <video id prefix> (D-056) gives a permanently failed job one more attempt; approvers only.
const retryCommand = /^\/retry(?:@\w+)?\s+([0-9a-fA-F-]{4,36}|last)\s*$/.exec(update.message?.text ?? '');
if (update.message && retryCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'retry',
      prefix: retryCommand[1].toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /auto <video id prefix> [off] (D-093) approves every remaining gate of the video (not the Mac
// cleanup) in the sender's name; off turns it back to buttons. telegram_auto() checks the approver.
const autoCommand = /^\/(?:auto|tudong)(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(update.message?.text ?? '');
if (update.message && autoCommand && !update.message.from?.is_bot) {
  // /auto all [off] (D-098): every active video, after a Confirm button; off needs none.
  const all = /^\s+all(?:\s+(off|tat))?\s*$/i.exec(autoCommand[1]);
  if (all) {
    return [{
      json: {
        kind: 'auto-all',
        enable: all[1] ? 'false' : 'true',
        userId: String(update.message.from.id),
        chatId: String(update.message.chat.id),
        messageId: String(update.message.message_id),
      },
    }];
  }
  const args = /^\s+([0-9a-fA-F-]{4,36}|last)(?:\s+(off|tat))?\s*$/i.exec(autoCommand[1]);
  return [{
    json: {
      kind: 'auto',
      prefix: args ? args[1].toLowerCase() : '',
      enable: args && args[2] ? 'false' : 'true',
      error: args ? '' : 'Cách dùng: /auto <8 ký tự đầu của id video> · tắt: /auto <id> off',
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /move <video id prefix> <worker id> (D-087) moves a video to another worker, which copies its
// files; /move <prefix> huy cancels a move still waiting. telegram_move() checks the owner.
const moveCommand = /^\/(?:move|chuyen)(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(update.message?.text ?? '');
if (update.message && moveCommand && !update.message.from?.is_bot) {
  const args = /^\s+([0-9a-fA-F-]{4,36}|last)\s+([a-zA-Z0-9][a-zA-Z0-9-]{1,40})\s*$/.exec(moveCommand[1]);
  const target = args ? args[2].toLowerCase() : '';
  return [{
    json: {
      kind: 'move',
      userId: String(update.message.from.id),
