      ? `Không có yêu cầu nào đang chờ duyệt cho video có id bắt đầu bằng ${input.prefix}.`
      : 'Không có yêu cầu nào đang chờ duyệt.');
  }
  return reply(input.prefix ? `Không có video nào có id bắt đầu bằng ${input.prefix}.` : 'Không có video nào đang chạy.');
}
// Vietnam time (UTC+7, no daylight saving): "14:30 30/10".
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const span = (m) => (m < 60 ? `${m} phút` : `${Math.floor(m / 60)} giờ ${String(m % 60).padStart(2, '0')} phút`);
const minutes = (from, to = Date.now()) => span(Math.max(0, Math.round((new Date(to).getTime() - new Date(from).getTime()) / 60_000)));
const seconds = (s) => (s < 60 ? `${s} giây` : span(Math.round(s / 60)));
// One-tap commands (D-102): Telegram makes only letters, digits and _ tappable.
const shortId = (id) => String(id).slice(0, 8);
const videoLink = (id) => `/v_${shortId(id)}`;
const retryLink = (id) => `/retry_${shortId(id)}`;
const workerLink = (id) => `/worker_${String(id).replace(/-/g, '_')}`;
const describe = (p) => {
  if (!p || !p.stage) return '';
  const turn = p.turn ? ` ${p.turn}/${p.of}` : '';
  switch (p.stage) {
    case 'agent': return `agent lượt${turn}`;
    case 'gates': return `đang kiểm tra (lượt${turn})`;
    case 'tts': return `lời đọc ${p.scene}/${p.of}`;
    case 'voice': return 'đang ghép giọng';
    case 'whisper': return 'whisper';
    case 'render': return `đang render ${p.frames ?? ''} khung hình`.replace('  ', ' ');
    case 'loudness': return 'chuẩn hóa âm lượng';
    case 'qa': return 'QA';
    case 'metadata': return `viết metadata (lần ${p.round ?? 1})`;
    case 'archive': return p.step === 'uploading' ? 'đang tải lên bản lưu' : 'đang gom file';
    case 'cleanup': return p.step === 'deleting' ? 'đang xóa bản trên Mac' : 'đang kiểm tra lại bản lưu';
    default: return String(p.stage);
  }
};
const workerState = (row) => `${row.online ? '🟢' : '🔴'} ${row.worker_id} · ${row.online ? 'online' : `offline${row.last_seen_at ? ` ${minutes(row.last_seen_at)}` : ''}`}`;
const jobDetail = (job) => [
  job.step,
  job.started ? minutes(job.started) : '',
  job.attempts > 1 ? `lần ${job.attempts}` : '',
  describe(job.progress),
  job.video_status,
].filter(Boolean).join(' · ');
// Open moves from or to this worker (D-087).
const moveLines = (row) => (row.moves ?? []).map((m) => `↪ ${videoLink(m.video_id)}: ${m.from_worker} → ${m.to_worker} · ${m.status === 'COPYING' ? `đang copy (lần ${m.attempts})` : 'đang chờ'}`);
// /workers (D-082): one block per worker, the clips it is running and the jobs waiting for it.
if (input.kind === 'workers') {
  const blocks = rows.map((row) => {
    const waiting = row.waiting > 0 ? ` · ${row.waiting} job đang chờ` : '';
    const running = (row.jobs ?? []).flatMap((job) => [
      `▶ ${videoLink(job.video_id)} v${job.version} · ${job.title ?? '?'}`,
      jobDetail(job),
    ]);
    return [`${workerState(row)}${waiting}`, ...(running.length ? running : ['rảnh']), ...moveLines(row), `Chi tiết: ${workerLink(row.worker_id)}`].join('\n');
  });
  return reply([`🖥 ${rows.length} worker`, ...blocks.flatMap((b) => ['', b])].join('\n'));
}
// /worker <id> (D-102): live state, the videos pinned to it and its last 24 hours.
if (input.kind === 'worker') {
  const row = rows[0];
  const jobs = row.jobs ?? [];
  const videos = row.videos ?? [];
  const hidden = row.videos_total - videos.length;
  const stats = row.stats ?? { succeeded: 0, failed: 0, completed: 0, slowest: [] };
  const seen = [
    row.last_seen_at ? `Heartbeat: ${vnTime(row.last_seen_at)}` : '',
    row.last_idle_at ? `Rảnh lần cuối: ${vnTime(row.last_idle_at)}` : '',
  ].filter(Boolean).join(' · ');
  return reply([
    workerState(row),
    ...(seen ? [seen] : []),
    ...(row.capabilities?.length ? [`Khả năng: ${row.capabilities.join(', ')}`] : []),
    '',
    ...(jobs.length
      ? ['▶ Đang chạy', ...jobs.flatMap((job) => [`${videoLink(job.video_id)} v${job.version} · ${job.title ?? '?'}`, jobDetail(job)])]
      : ['Rảnh, không chạy job nào.']),
    ...moveLines(row),
    '',
    videos.length
      ? `📌 ${row.videos_total} video trên máy này${row.waiting > 0 ? ` · ${row.waiting} job đang chờ` : ''}`
      : '📌 Không có video nào trên máy này',
    ...videos.map((v) => `${videoLink(v.video_id)} v${v.version} · ${v.approval ? `chờ ${v.approval}` : v.status}`),
    ...(hidden > 0 ? [`… và ${hidden} video nữa`] : []),
    '',
    `📈 24 giờ: ${stats.succeeded} bước xong · ${stats.failed} lỗi · ${stats.completed} video hoàn tất`,
    ...(stats.slowest.length ? [`Chậm nhất: ${stats.slowest.map((s) => `${s.step} ${seconds(s.median_seconds)}`).join(', ')}`] : []),
  ].join('\n'));
}

// /pending (D-090): one line per open request; telegram_pending() made those with a reminder path
// due, so their workflows send them again with buttons on the next 30 s poll.
if (input.kind === 'pending') {
  const STOPPED = { NEEDS_DECISION: (id) => [`chạy lại: ${retryLink(id)}`], BLOCKED_PROVIDER: () => [] };
  const label = (row) => [`${videoLink(row.video_id)} v${row.version}`, row.title ?? '?', row.type];
  const open = rows.filter((row) => !STOPPED[row.type]);
  const stopped = rows.filter((row) => STOPPED[row.type]);
  const lines = open.map((row) => [
    ...label(row),
    `hạn ${vnTime(row.expires_at)}`,
    ...(row.reminded ? [] : ['nút nằm trong tin báo hoàn tất']),
  ].join(' · '));
  const resent = open.filter((row) => row.reminded).length;
  // Stopped videos (D-097) wait for someone too, but have no request to send again.
  const stoppedLines = stopped.map((row) => [...label(row), ...STOPPED[row.type](row.video_id)].join(' · '));
  return reply([
    ...(open.length ? [`⏳ ${open.length} yêu cầu đang chờ duyệt`, '', ...lines] : []),
    ...(resent ? ['', `Bot sẽ gửi lại ${resent} yêu cầu kèm nút trong khoảng 30 giây.`] : []),
    ...(open.length && stopped.length ? [''] : []),
    ...(stopped.length ? [`⛔ ${stopped.length} video đang dừng`, '', ...stoppedLines] : []),
  ].join('\n'));
}

const head = (row) => `${shortId(row.video_id)} v${row.version} · ${row.title ?? '?'}`;
// telegram_status() says "<type> until <YYYY-MM-DD HH:MI> UTC"; shown in Vietnam time.
const approval = (row) => String(row.approval)
  .replace(/ until (\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}) UTC/, (_, day, time) => `, hạn ${vnTime(`${day}T${time}:00Z`)}`);
const cost = (row) => Object.entries(row.cost ?? {}).map(([c, v]) => `${Math.round(v * 100) / 100} ${c}`).join(', ');

if (input.prefix) {
  const row = rows[0];
  const marks = { SUCCEEDED: '✓', RUNNING: '▶', FAILED_PERMANENT: '✗', FAILED_RETRYABLE: '↻', BLOCKED: '⏸' };
  const jobs = (row.jobs ?? []).map((job) => {
    const parts = [`${marks[job.status] ?? '·'} ${job.step}`];
    if (job.started) parts.push(minutes(job.started, job.status === 'RUNNING' ? undefined : job.finished ?? undefined));
    else parts.push('đang chờ');
    if (job.attempts > 1) parts.push(`${job.attempts} lần chạy`);
    if (job.status === 'RUNNING' && describe(job.progress)) parts.push(describe(job.progress));
    if (job.error && job.status !== 'SUCCEEDED') parts.push(job.error);
    return parts.join(' · ');
  });
  const detail = reply([
    `📊 Video ${head(row)}`,
    row.worker_id ? `🖥 Worker: ${workerLink(row.worker_id)} ${row.worker_online ? '🟢' : '🔴'}` : '🖥 Worker: chưa gán',
    `Trạng thái: ${row.status} (${minutes(row.status_since)})`,
    ...jobs,
    cost(row) ? `Chi phí: ${cost(row)}` : 'Chi phí: chưa ghi nhận',
    ...(row.approval ? [`Đang chờ: ${approval(row)}`] : []),
    ...(row.status === 'NEEDS_DECISION' ? [`Chạy lại bước lỗi: ${retryLink(row.video_id)}`] : []),
  ].join('\n'));
  if (!input.card) return detail;
  // /v (D-099): the same text, plus a button per action bound to this version.
  const hex = String(row.video_id).replace(/-/g, '');
  const button = (action) => `v:${action}:${hex}:${row.version}`;
  return [{
    json: {
      ...detail[0].json,
      card: true,
      retryData: button('R'),
      autoData: button('A'),
      pendingData: button('P'),
      cancelData: button('C'),
    },
  }];
}

// /status (D-102): grouped by what the video needs, the order telegram_status() already returns.
const TITLE_LIMIT = 40;
const shortTitle = (title) => (title && title.length > TITLE_LIMIT ? `${title.slice(0, TITLE_LIMIT)}…` : title ?? '?');
const workerTag = (row) => (row.worker_id ? `🖥 ${row.worker_id}${row.worker_online ? '' : ' 🔴'}` : '🖥 chưa gán');
const STEP_MARKS = { FAILED_PERMANENT: '✗', FAILED_RETRYABLE: '↻', BLOCKED: '⏸' };
const jobCount = (row) => `${row.steps_done}/${row.steps_total} job`;
const GROUPS = [
  {
    name: 'STOPPED', icon: '⛔', count: 'dừng', title: 'CẦN XỬ LÝ',
    lines: (row) => {
      const retry = row.status === 'NEEDS_DECISION' ? [retryLink(row.video_id)] : [];
      const step = row.step ? [`${STEP_MARKS[row.step_status] ?? '·'} ${row.step}`] : [];
      const next = [...step, ...retry];
      return [`${workerTag(row)} · ${row.status}`, ...(next.length ? [next.join(' · ')] : [])];
    },
  },
  {
    name: 'APPROVAL', icon: '⏳', count: 'chờ duyệt', title: 'CHỜ DUYỆT',
    lines: (row) => [`${workerTag(row)} · ${approval(row)}`],
  },
  {
    name: 'RUNNING', icon: '▶', count: 'chạy', title: 'ĐANG CHẠY',
    lines: (row) => [[workerTag(row), `${row.step} ${minutes(row.step_since)}`, describe(row.progress), jobCount(row)].filter(Boolean).join(' · ')],
  },
  {
    name: 'WAITING', icon: '🕒', count: 'chờ', title: 'ĐANG CHỜ',
    lines: (row) => [[
      workerTag(row),
      row.status,
      row.step ? `${row.step} ${String(row.step_status).toLowerCase()} ${minutes(row.step_since)}` : 'chưa có job',
      jobCount(row),
    ].join(' · ')],
  },
];
const filled = GROUPS
  .map((group) => ({ ...group, rows: rows.filter((row) => row.state_group === group.name) }))
  .filter((group) => group.rows.length > 0);
const total = rows[0].total;
const summary = [
  `📊 ${total > rows.length ? `hiện ${rows.length}/${total}` : rows.length} video`,
  ...filled.map((group) => `${group.icon} ${group.rows.length} ${group.count}`),
].join(' · ');
const sections = filled.flatMap((group) => [
  '',
  `${group.icon} ${group.title}`,
  ...group.rows.flatMap((row) => [`${videoLink(row.video_id)} v${row.version} · ${shortTitle(row.title)}`, ...group.lines(row)]),
