// /new -> the brief, the chosen worker (D-087, '' = Tự động) and auto=on (D-096) for telegram_intake_draft() (D-058);
// a parse error becomes the reply instead.
// The full brief file is read as UTF-8 text and kept verbatim (only a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const fullBrief = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : '';
const brief = {
  topic: input.topic,
  ...(input.minutes ? { duration_minutes: input.minutes } : {}),
  ...(fullBrief.trim() ? { full_brief: fullBrief } : {}),
  ...(input.notes ? { notes: input.notes } : {}),
  ...(input.selection ?? {}),
};
return [{ json: { ...reply, ok: true, userId: input.userId, worker: input.worker ?? '', auto: String(input.auto === true), brief: JSON.stringify(brief) } }];

// telegram_intake_draft() / telegram_intake_cycle() -> the confirmation with Tạo / Hủy and the
// Kit / Nhân vật / Worker / Thời lượng buttons (callback in:<A|R|K|C|W|D>:<token>, D-066, D-087, D-091), or the reason
// nothing was drafted. A full brief's length follows its VOICE section: the draft shows the estimate
// and its button is refused (FULL_BRIEF). A cycle edits the bot's own message (edit: true); an idea button (D-083) sends a new one. Telegram text is Vietnamese (D-061).
// Vietnam time (UTC+7, no daylight saving): "14:30 30/10".
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const edit = input.kind === 'intake-set';
const reply = { chatId: input.chatId, messageId: input.messageId, queryId: input.queryId ?? '', edit };
if (row.result === 'NOT_APPROVER') return [{ json: { ...reply, edit: false, text: 'Bạn không phải approver.' } }];
if (row.result !== 'DRAFT') {
  const closed = { NOT_FOUND: 'Không tìm thấy bản nháp này.', NOT_PENDING: 'Bản nháp đã được quyết định rồi.', EXPIRED: 'Bản nháp đã hết hạn; gửi /new lại.', IDEA_NOT_FOUND: 'Không tìm thấy ý tưởng này.', IDEA_EXPIRED: 'Ý tưởng đã hết hạn (7 ngày); gửi /ideas để lấy ý tưởng mới.', IDEA_USED: 'Ý tưởng này đang có bản nháp hoặc đã tạo video.', FULL_BRIEF: 'Có full brief: thời lượng theo mục VOICE, không chọn được. Muốn ngắn hơn thì bớt câu trong VOICE.', UNCHANGED: 'Không có lựa chọn khác để đổi.' };
  const text = edit || input.kind === 'idea-pick' ? (closed[row.result] ?? `Không đổi được (${row.result ?? 'không có phản hồi'}).`) : `Chưa tạo: ${row.error ?? row.result ?? 'không có phản hồi'}`;
  return [{ json: { ...reply, edit: false, text } }];
}
const brief = typeof row.brief === 'string' ? JSON.parse(row.brief) : row.brief;
const selection = typeof row.selection === 'string' ? JSON.parse(row.selection) : row.selection;
const duration = selection.duration;
const voiceEstimate = (d) => d.voice_words == null
  ? 'theo VOICE (chưa ước tính được)'
  : `theo VOICE, ước tính ~${String(d.voice_minutes).replace('.', ',')} phút (${d.voice_words} từ)`;
const durationLine = duration?.follows_voice
  ? voiceEstimate(duration)
  : duration?.label ?? (brief.duration_minutes ? `khoảng ${brief.duration_minutes} phút` : 'không đặt (khoảng 6 phút)');
const text = [
  '🆕 Tập mới: xác nhận',
  `Chủ đề: ${brief.topic}`,
  `Kit: ${selection.kit.label} · Nhân vật: ${selection.character_set.label}`,
  `Worker: ${selection.worker?.label ?? 'Tự động'}`,
  ...(selection.auto ? ['Tự duyệt: Bật — mọi bước tới khi lưu Drive (trừ xóa bản trên Mac)'] : []),
  ...(brief.series ? [`Series: ${brief.series.title} · tập ${brief.series.episode}`] : []),
  ...(brief.related_to?.title ? [`Liên quan: ${brief.related_to.title}`] : []),
  `Thời lượng: ${durationLine}`,
  `Full brief: ${brief.full_brief ? `${brief.full_brief.length} ký tự` : 'không có (Claude tự viết tập)'}`,
  ...(brief.notes ? [`Ghi chú: ${brief.notes}`] : []),
  ...(row.has_voice === false
    ? ['', 'Cảnh báo: full brief không có mục VOICE. Khi có full brief, kịch bản phải chép nguyên văn từng câu thoại từ đó, nên brief này sẽ lỗi. Hãy thêm mục VOICE, hoặc gửi dàn ý dưới dạng ghi chú.']
    : []),
  '',
  `⏰ Hạn ${vnTime(row.expires_at)}`,
].join('\n');
return [{
  json: {
    ...reply,
    text,
    approve: `in:A:${row.token}`,
    reject: `in:R:${row.token}`,
    kitButton: `Kit → ${selection.kit.next_label}`,
    kitData: `in:K:${row.token}`,
    castButton: `Nhân vật → ${selection.character_set.next_label}`,
    castData: `in:C:${row.token}`,
    workerButton: `Worker → ${selection.worker?.next_label ?? 'Tự động'}`,
    workerData: `in:W:${row.token}`,
    durationButton: duration?.follows_voice ? 'Thời lượng: theo VOICE' : `Thời lượng → ${duration?.next_label ?? '3 phút'}`,
    durationData: `in:D:${row.token}`,
  },
}];

// A rules command -> the arguments of telegram_rules() (D-059); a usage error becomes the reply.
// A /rules set file is read as UTF-8 (a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const text = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : input.text;
return [{
  json: {
    ...reply,
    ok: true,
    userId: input.userId,
    action: input.action,
    scope: input.scope,
    text,
    extra: input.extra,
  },
}];

// telegram_rules() -> the reply (D-059): the rules list, a confirmation, a refusal, or a Markdown
// file to edit (/rules file). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
const say = (text) => [{ json: { ...reply, exportFile: false, text: text.slice(0, 4096) } }];
if (row.result === 'NOT_APPROVER') return say('Bạn không phải approver.');
if (row.result === 'INVALID') return say(`Chưa thay đổi: ${row.detail}`);
if (row.result === 'NOT_FOUND') {
  return say(input.action === 'DELETE' ? `Không có quy tắc #${row.detail}.` : `Chưa có cách đọc cho "${row.detail}".`);
}
if (row.result !== 'OK') return say(`Quy tắc: ${row.result ?? 'không có phản hồi'}`);
const rules = typeof row.rules === 'string' ? JSON.parse(row.rules) : row.rules;
const names = { video: 'video', tts: 'TTS', pronunciation: 'phát âm' };
const items = (scope) =>
  scope === 'pronunciation'
    ? rules.pronunciation.map((p) => `${p.term} = ${p.spoken}`)
    : rules[scope].map((r) => `#${r.id} ${r.text}`);
if (input.exportFile) {
  const scope = input.scope;
  const header = scope === 'pronunciation'
    ? ['# Phát âm', '', 'Mỗi mục là một dòng "từ = cách đọc" (phân biệt hoa thường, khớp nguyên từ); các dòng khác bị bỏ qua.']
    : [`# Quy tắc ${names[scope]}`, '', 'Mỗi mục danh sách là một quy tắc; các dòng khác bị bỏ qua.'];
  const list = scope === 'pronunciation' ? items(scope) : rules[scope].map((r) => r.text);
  return [{
    json: {
      ...reply,
      exportFile: true,
      fileName: `${scope === 'pronunciation' ? 'say' : scope}-rules.md`,
      markdown: [...header, '', ...list.map((item) => `- ${item}`), ''].join('\n'),
      caption: `Sửa xong gửi lại với caption /rules set ${scope === 'pronunciation' ? 'say' : scope}`,
    },
  }];
}
const done = {
  ADD: () => `Đã thêm quy tắc #${row.detail} (${names[input.scope]}).`,
  DELETE: () => `Đã xóa quy tắc #${input.text}.`,
  SET: () => `Đã thay toàn bộ quy tắc ${names[input.scope]}: giờ có ${rules[input.scope].length} mục.`,
  SAY: () => `"${input.text}" giờ được đọc là "${input.extra}".`,
  UNSAY: () => `"${input.text}" lại được đọc như chữ viết.`,
}[input.action];
if (done) return say(`${done()} Áp dụng cho các bước bắt đầu từ bây giờ.`);
const scopes = input.scope ? [input.scope] : ['video', 'tts', 'pronunciation'];
const lines = scopes.flatMap((scope) => ['', `${names[scope][0].toUpperCase()}${names[scope].slice(1)}:`, ...(items(scope).length ? items(scope) : ['(chưa có)'])]);
const text = [`Quy tắc kênh (phiên bản ${String(rules.version).slice(0, 8)})`, ...lines, '', 'Sửa: /rule add video|tts <nội dung> · /rule del <số> · /say <từ> = <cách đọc> · /unsay <từ> · /rules file video|tts|say'].join('\n');
return say(text.length > 4096 ? `${text.slice(0, 3900)}\n…\nQuá dài cho một tin nhắn: dùng /rules file video|tts|say.` : text);

// The rules as a Markdown file for /rules file (D-059).
const row = $input.first().json;
const data = await this.helpers.prepareBinaryData(Buffer.from(row.markdown, 'utf8'), row.fileName, 'text/markdown');
return [{ json: { chatId: row.chatId, messageId: row.messageId, caption: row.caption }, binary: { data } }];

// telegram_members() -> the reply (D-060): a join request for the owner with Approve / Reject
// (callback mb:<A|R>:<token>), the approver list, or why nothing changed. Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
const say = (text) => [{ json: { ...reply, text } }];
const list = (members) => {
  const rows = typeof members === 'string' ? JSON.parse(members) : members ?? [];
  return [
    `Approver (${rows.length})`,
    ...rows.map((m) => `${m.owner ? '★' : '-'} ${m.name} (id ${m.user_id})${m.owner ? ' · chủ sở hữu' : ''}`),
    '',
    'Chủ sở hữu có thể gỡ một người bằng /revoke <user id>.',
  ].join('\n');
};
switch (row.result) {
  case 'REQUESTED':
    return [{
      json: {
        ...reply,
        text: [
          `${input.name} (id ${input.userId}) xin làm approver.`,
          'Chỉ chủ sở hữu mới duyệt được. Yêu cầu hết hạn sau 72 giờ.',
        ].join('\n'),
        approve: `mb:A:${row.token}`,
        reject: `mb:R:${row.token}`,
      },
    }];
  case 'ALREADY_MEMBER': return say('Bạn đã là approver rồi.');
  case 'ALREADY_REQUESTED': return say('Yêu cầu của bạn đang chờ chủ sở hữu duyệt.');
  case 'NO_OWNER': return say('Chưa đặt chủ sở hữu nên chưa ai duyệt được thành viên mới.');
  case 'NOT_APPROVER': return say('Bạn không phải approver.');
  case 'NOT_OWNER': return say('Chỉ chủ sở hữu mới làm được việc này.');
  case 'NOT_FOUND': return say(`${row.detail} không phải approver.`);
  case 'INVALID': return say(`Chưa thay đổi: ${row.detail}`);
  case 'OK':
    return say(input.action === 'REVOKE' ? `${row.detail} không còn là approver.\n\n${list(row.members)}` : list(row.members));
  default: return say(`Thành viên: ${row.result ?? 'không có phản hồi'}`);
}

// telegram_ideas() rows -> one reply (D-083), or the parse error. Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const reply = (text) => [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];
if (input.error) return reply(input.error);
const rows = $input.all().map((item) => item.json).filter((row) => row.result);
if (rows.length === 0) return reply('Không có phản hồi từ cơ sở dữ liệu.');
if (rows.some((row) => row.result === 'NOT_APPROVER')) return reply('Bạn không phải approver.');
const pair = (row) => `${row.kit} · ${row.character_set}`;
const line = (row) => {
  switch (row.result) {
    case 'QUEUED': return `⏳ ${pair(row)}: đang nghĩ ý tưởng…`;
    case 'BUSY': return `⏳ ${pair(row)}: ý tưởng đang được viết, chờ chút.`;
    case 'UNKNOWN_KIT': return `Không có kit "${row.kit}".`;
    case 'UNKNOWN_CHARACTER': return `Không có nhân vật "${row.character_set}".`;
    case 'NO_PAIR': return 'Không có cặp kit + nhân vật nào để viết ý tưởng.';
    default: return `${pair(row)}: ${row.result}`;
  }
};
const queued = rows.some((row) => row.result === 'QUEUED');
return reply([...rows.map(line), ...(queued ? ['', 'Ý tưởng sẽ gửi vào chat này khi xong (thường vài phút).'] : [])].join('\n'));
